const fs=require('node:fs'),path=require('node:path');
const root=path.resolve(process.argv[2]), queryFile=process.argv[3];
const app=require(path.join(root,'app.js'));
const docs=fs.readdirSync(path.join(root,'inputs')).map(name=>{
  const text=fs.readFileSync(path.join(root,'inputs',name),'utf8');
  return {name,text,status:app.classify(name,text)};
});
const cases=JSON.parse(fs.readFileSync(queryFile,'utf8')).query_cases;
console.log(JSON.stringify({scope:'Original final G classifier/search functions, no DOM/browser or maintenance-path check',
  classifications:docs.map(d=>({name:d.name,status:d.status})),
  queries:cases.map(c=>({query:c.query,results:app.search(docs,c.query,false).map(r=>({name:r.doc.name,text:r.doc.text,score:r.score}))}))},null,2));
